insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_118'
from (values
('127.821.d.1.A',3,'Marisol wants to weld pipelines after graduation. She reads the Texas college catalog to see which math, blueprint and certification courses lead to that job. She is exploring:','["academic knowledge and skills needed for postsecondary education and careers", "only the football schedule", "only the cafeteria menu", "only the parking rules"]'::jsonb,0,'Course requirements shape the path.','original'),
('127.821.d.1.A',4,'Which plan best prepares a high school welding student for a two-year welding technology program?','["avoid any shop classes", "take geometry and blueprint reading while earning an entry-level AWS credential", "wait until after graduation to start", "skip math and focus on art only"]'::jsonb,1,'Math, print reading and credentials transfer.','original'),
('127.821.d.1.B',3,'A fabrication customer calls twice about a late handrail order. The owner tells the crew that meeting delivery dates and quality is what keeps clients coming back. This shows employers'' expectations that foster:','["less paperwork", "shorter lunch breaks", "positive customer satisfaction", "higher shop rent"]'::jsonb,2,'Delivery and quality satisfy customers.','original'),
('127.821.d.1.B',4,'A welder finishes a trailer hitch ahead of schedule but notices a crooked bracket. To meet the employer''s expectations she should:','["wait for a complaint", "blame the cutter", "ship it and hope no one notices", "fix the bracket before it leaves the shop"]'::jsonb,3,'Quality is part of satisfaction.','original'),
('127.821.d.1.C',3,'Devon arrives ten minutes early, puts on his PPE without being reminded, and thanks the lead for feedback. Which workplace standard is he showing?','["dependability and respect", "secrecy", "carelessness", "impatience"]'::jsonb,0,'Reliability and courtesy are professional standards.','original'),
('127.821.d.1.C',4,'A coworker keeps leaving cut-off scraps on the floor around her booth. Which standard is she missing?','["parking neatly", "keeping a safe, orderly work area", "speaking quietly", "wearing a belt"]'::jsonb,1,'Housekeeping is a professional standard.','original'),
('127.821.d.1.D',3,'At the start of each semester, Jada rereads her written goal to earn a structural welding certificate and checks which steps are done. She is:','["ordering supplies", "grading a test", "evaluating her personal career goals", "tuning equipment"]'::jsonb,2,'Review of goals keeps a plan on track.','original'),
('127.821.d.1.D',4,'After failing a bend test, Jada decides to add practice time and ask the instructor for tips. This shows an evaluation that leads to:','["abandoning the career", "hiding the result", "blaming the equipment", "revising the plan to reach the career goal"]'::jsonb,3,'Evaluate, then adjust.','original'),
('127.821.d.1.E',3,'Before starting a rush job, Eli repeats the drawing number, weld size and due date back to the supervisor. He does this to:','["clarify objectives and avoid mistakes", "delay the work", "impress a visitor", "change the order"]'::jsonb,0,'Repeating details confirms understanding.','original'),
('127.821.d.1.E',4,'The work order says ''weld the frame'' but gives no joint type. The best communication step is to:','["guess and begin", "ask the supervisor which weld is required", "skip the frame", "use the cheapest rod"]'::jsonb,1,'Clarify before welding.','original'),
('127.821.d.1.F',3,'A shop posts safety data sheets, requires eye protection at the grinders and runs fire drills. These steps support:','["parking rules", "payroll rules", "health and safety requirements set by OSHA", "marketing goals"]'::jsonb,2,'OSHA sets workplace safety standards.','original'),
('127.821.d.1.F',4,'A new hire sees an unlabeled spray bottle near the welding table. The best safety action is to:','["pour it down the drain", "take it home", "spray it on the metal", "report it and avoid using it until it is identified"]'::jsonb,3,'Unknown chemicals can be hazardous.','original'),
('127.821.d.2.A',3,'A customer who speaks little English visits the shop to ask about a gate. The welder uses simple words, a sketch and a tape measure to confirm the size. This demonstrates:','["effective communication with people from varied backgrounds", "ignoring the customer", "rushing the sale", "using only jargon"]'::jsonb,0,'Sketches and simple words bridge gaps.','original'),
('127.821.d.2.A',4,'When talking with a new supplier whose first language differs, the best habit is to:','["talk faster", "speak clearly and confirm understanding with a written note", "use slang", "avoid the topic"]'::jsonb,1,'Confirming prevents errors.','original'),
('127.821.d.2.B',3,'A job needs 18 feet of 2-inch tube at $3.50 per foot plus $42 of rod. The estimated material cost is:','["$84", "$147", "$105", "$63"]'::jsonb,2,'18 × 3.50 = 63, plus 42 = 105.','original'),
('127.821.d.2.B',4,'A fabricator estimates 6 hours of labor at $28 per hour plus $95 in materials and adds a 10% markup to the total. The bid is:','["$310", "$273", "$263", "$289.30"]'::jsonb,3,'168 + 95 = 263; ×1.10 = 289.30.','original'),
('127.821.d.2.C',3,'A work order should list the customer, the job description, materials and due date because it:','["tells everyone what to build and by when", "hides the cost", "avoids planning", "replaces the drawing"]'::jsonb,0,'Work orders communicate the task.','original'),
('127.821.d.2.C',4,'Which sentence is the best technical writing for a work order?','["Make it look good.", "Weld two 3/16 in. fillets on all joints of frame A by Friday.", "Do the frame stuff soon.", "Weld it however."]'::jsonb,1,'Specific and measurable.','original'),
('127.821.d.2.D',3,'An apprentice reads a vernier caliper at 1.375 in. and a tape at 1 3/8 in. for the same bar. The readings:','["disagree by 1/4", "cannot be compared", "agree, since 1.375 equals 1 3/8", "disagree by 1/8"]'::jsonb,2,'3/8 = 0.375.','original'),
('127.821.d.2.D',4,'Reading a tape measure, a mark halfway between 2 1/4 in. and 2 3/8 in. is:','["2 7/16 in.", "2 3/16 in.", "2 1/2 in.", "2 5/16 in."]'::jsonb,3,'Halfway is 2 5/16.','original'),
('127.821.d.2.E',3,'To check that a fabricated corner is exactly 90 degrees, the welder should use a:','["framing or combination square", "scale", "stopwatch", "thermometer"]'::jsonb,0,'Squares check right angles.','original'),
('127.821.d.2.E',4,'Which tool best measures the leg size of a finished fillet weld?','["straight edge only", "fillet weld gauge", "feeler gauge for spark plugs", "micrometer for wire"]'::jsonb,1,'Fillet gauges show leg size.','original'),
('127.821.d.2.F',3,'A rectangular steel plate is 24 in. by 18 in. Its area is:','["42 square inches", "84 square inches", "432 square inches", "864 square inches"]'::jsonb,2,'24 × 18 = 432.','original'),
('127.821.d.2.F',4,'A rectangular tank is 4 ft long, 3 ft wide and 2 ft tall. Its volume is:','["48 cubic feet", "12 cubic feet", "9 cubic feet", "24 cubic feet"]'::jsonb,3,'4 × 3 × 2 = 24.','original'),
('127.821.d.2.G',3,'A welder cuts three pieces measuring 4 1/2, 3 3/4 and 2 1/4 inches. The total length is:','["10 1/2 inches", "11 inches", "10 inches", "9 1/2 inches"]'::jsonb,0,'4.5+3.75+2.25 = 10.5.','original'),
('127.821.d.2.G',4,'From a 12.75 in. bar, a welder cuts 4 5/8 in. The remaining length is:','["8 3/8 in.", "8 1/8 in.", "7 7/8 in.", "8 1/4 in."]'::jsonb,1,'12.75 − 4.625 = 8.125.','original'),
('127.821.d.2.H',3,'A welder uses a calculator to find the number of 7.5-inch brackets that can be cut from a 120-inch bar. The answer is:','["15", "18", "16", "17"]'::jsonb,2,'120 ÷ 7.5 = 16.','original'),
('127.821.d.2.H',4,'Which method is a reasonable check on a calculator result for 49.8 × 3.02?','["add instead", "use 100 × 10", "ignore it", "estimate with 50 × 3 = 150"]'::jsonb,3,'Estimation catches entry errors.','original'),
('127.821.d.2.I',3,'A drawing calls for a 5/8 in. hole. As a decimal, this is:','["0.625 in.", "0.58 in.", "0.5 in.", "0.85 in."]'::jsonb,0,'5 ÷ 8 = 0.625.','original'),
('127.821.d.2.I',4,'A shop caliper reads 0.4375 in. The same size as a fraction is:','["1/2 in.", "7/16 in.", "9/16 in.", "3/8 in."]'::jsonb,1,'0.4375 = 7/16.','original'),
('127.821.d.2.J',3,'A metric drawing calls for a plate 50.8 mm thick. In inches, that is:','["1 in.", "1.5 in.", "2 in.", "5 in."]'::jsonb,2,'50.8 ÷ 25.4 = 2.','original'),
('127.821.d.2.J',4,'A 3/4 in. diameter rod is about how many millimeters?','["7.5 mm", "25 mm", "34 mm", "19 mm"]'::jsonb,3,'0.75 × 25.4 ≈ 19.','original'),
('127.821.d.2.K',3,'A brace runs diagonally across a rectangular frame 3 ft by 4 ft. Using the Pythagorean theorem, its length is:','["5 ft", "7 ft", "12 ft", "6 ft"]'::jsonb,0,'3²+4²=25; √25=5.','original'),
('127.821.d.2.K',4,'A right-triangle gusset has legs of 6 in. and 8 in. The hypotenuse is:','["14 in.", "10 in.", "9 in.", "12 in."]'::jsonb,1,'36+64=100.','original'),
('127.821.d.2.L',3,'On a circle diagram, the straight line from edge to edge through the center is the:','["sector", "tangent", "diameter", "arc"]'::jsonb,2,'Diameter passes through the center.','original'),
('127.821.d.2.L',4,'A pipe diagram labels the distance from the center to the outside edge as 3 in. This distance is the:','["chord", "circumference", "diameter", "radius"]'::jsonb,3,'Radius is half the diameter.','original'),
('127.821.d.3.A',3,'Before striking an arc, Priya checks the cable insulation, ground clamp and the area for flammable rags. She is:','["operating welding equipment according to safety standards", "painting a part", "packing a truck", "setting a price"]'::jsonb,0,'Pre-use checks follow safety standards.','original'),
('127.821.d.3.A',4,'A welder sees the cable insulation worn through near the electrode holder. The correct step is to:','["wrap it with tape later", "stop and have the cable repaired or replaced", "move it to a dry spot", "keep welding"]'::jsonb,1,'Damaged cables are shock hazards.','original'),
('127.821.d.3.B',3,'A shop has used degreaser, spent flux and oily rags. Which is the proper way to handle them?','["burn them outside", "throw them in the trash", "store them in labeled approved containers for licensed disposal", "pour them on the lot"]'::jsonb,2,'Hazardous waste has rules.','original'),
('127.821.d.3.B',4,'A can of used solvent is nearly full. The environmentally correct action is to:','["leave it open to evaporate", "pour it into a floor drain", "dump it in the dirt", "close it, label it and arrange hazardous waste pickup"]'::jsonb,3,'Evaporation and drains pollute.','original'),
('127.821.d.3.C',3,'A shop sells steel cut-offs to a metal recycler each month. This practice:','["conserves resources and reduces landfill waste", "increases pollution", "wastes energy", "raises disposal costs"]'::jsonb,0,'Recycling saves material and energy.','original'),
('127.821.d.3.C',4,'Which welding material is most commonly recycled in large amounts?','["flux smoke", "scrap steel", "used gloves", "slag chips"]'::jsonb,1,'Steel scrap is widely recycled.','original'),
('127.821.d.3.D',3,'For overhead welding, a student chooses a helmet, leather jacket, gloves, cap and boots. These items make up:','["tool storage", "a work order", "personal protective equipment", "shop inventory"]'::jsonb,2,'PPE protects the welder.','original'),
('127.821.d.3.D',4,'Which choice is the best footwear when welding?','["canvas sneakers", "bare feet", "open sandals", "leather boots with the pant legs over the tops"]'::jsonb,3,'Covered leather boots shed sparks.','original'),
('127.821.d.3.E',3,'At the end of the month, Ben compares the number of near-miss reports and decides to start stricter PPE checks. He is:','["evaluating health and safety skills", "ordering rods", "building a table", "changing prices"]'::jsonb,0,'Evaluation leads to improvement.','original'),
('127.821.d.3.E',4,'An evaluation shows hearing protection is skipped at the grinders. The best improvement is to:','["remove the grinders", "post a reminder and check compliance each shift", "buy louder tools", "ignore it"]'::jsonb,1,'Consistent checks raise compliance.','original'),
('127.821.d.4.A',3,'Before cutting steel, a welder reads a drawing that shows lengths, hole sizes and notes. This shows knowledge of:','["phone books", "bus maps", "engineering drawings", "menu boards"]'::jsonb,2,'Drawings communicate design.','original'),
('127.821.d.4.A',4,'The title block of an engineering drawing usually gives the:','["welder''s lunch order", "shop''s payroll", "customer''s phone password", "part name, scale and drawing number"]'::jsonb,3,'Title blocks identify the drawing.','original'),
('127.821.d.4.B',3,'A drawing shows the front, top and right-side views of a bracket as flat, separate pictures. These are:','["orthographic views", "isometric views only", "photographs", "cutaway models"]'::jsonb,0,'Orthographic views are flat projections.','original'),
('127.821.d.4.B',4,'Which view shows three faces of a part in one picture, with width, depth and height at an angle?','["top", "isometric", "front", "side"]'::jsonb,1,'Isometric views show all three dimensions.','original'),
('127.821.d.4.C',3,'A welder reads a chart that lists plate thickness and recommended amperage. This is:','["calling a vendor", "cutting a shape", "interpreting a chart", "painting a part"]'::jsonb,2,'Charts give specifications.','original'),
('127.821.d.4.C',4,'On a print, a dashed line most commonly represents:','["the center of the shop", "a weld bead", "a welding arc", "a hidden edge"]'::jsonb,3,'Dashed lines show hidden features.','original'),
('127.821.d.4.D',3,'On a drawing, a triangle under the reference line, a number to its left and an arrow pointing to the joint are parts of the:','["welding symbol", "bill of materials", "scale bar", "title block"]'::jsonb,0,'The symbol communicates the weld.','original'),
('127.821.d.4.D',4,'In a welding symbol, a small flag at the bend of the reference line means the weld is to be made:','["underwater", "in the field", "on a sheet only", "in the shop only"]'::jsonb,1,'Field weld flag.','original'),
('127.821.d.4.E',3,'Two plates lying flat with one overlapping the other form a:','["edge joint", "corner joint", "lap joint", "butt joint"]'::jsonb,2,'Overlapping plates are a lap joint.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_118'
from (values
('127.821.d.4.E',4,'Two plates placed end to end in the same plane form a:','["lap joint", "corner joint", "tee joint", "butt joint"]'::jsonb,3,'End-to-end in-line plates are butt joints.','original'),
('127.821.d.4.F',3,'A weld made on a plate lying horizontally, with the welder looking down on the joint, is in the:','["flat position", "overhead position", "vertical position", "horizontal position"]'::jsonb,0,'Flat means welded from above.','original'),
('127.821.d.4.F',4,'Welding upward on a joint standing on end is in the:','["overhead position", "vertical position", "flat position", "horizontal position"]'::jsonb,1,'Vertical joints are welded up or down.','original'),
('127.821.d.4.G',3,'A triangular weld at the intersection of two plates at right angles is a:','["plug weld", "groove weld", "fillet weld", "spot weld"]'::jsonb,2,'Fillets are triangular.','original'),
('127.821.d.4.G',4,'A weld made in a hole in the top plate to join it to the one below is a:','["fillet weld", "flange weld", "groove weld", "plug weld"]'::jsonb,3,'Plug welds fill a hole.','original'),
('127.821.d.5.A',3,'After welding a trailer frame, a lead inspects the welds with a light and a gauge to look for cracks, undercut and incomplete fusion. This is:','["a weld inspection process", "a painting step", "a pricing step", "a packing step"]'::jsonb,0,'Visual inspection checks quality.','original'),
('127.821.d.5.A',4,'The first and most common weld inspection method is:','["radiography", "visual inspection", "ultrasonic only", "magnetic particle only"]'::jsonb,1,'Visual inspection comes first.','original'),
('127.821.d.5.B',3,'An inspector uses a code book to decide whether a pipeline weld''s undercut is acceptable. She is:','["tuning a tool", "setting a price", "interpreting a welding code", "ordering lunch"]'::jsonb,2,'Codes define acceptance.','original'),
('127.821.d.5.B',4,'A welding code mainly provides:','["a list of prices", "a shop schedule", "uniform colors", "minimum requirements for weld quality and procedure"]'::jsonb,3,'Codes set standards.','original'),
('127.821.d.6.A',3,'Rosa is about to light a cutting torch in a corner of the shop. Which action follows safe operating practice?','["check that no flammables are nearby and use a striker to light it", "leave the cylinders lying down", "point it toward a coworker", "light it with a pocket lighter near the hose"]'::jsonb,0,'Clear area and proper striker.','original'),
('127.821.d.6.A',4,'After finishing a cut, the operator should shut off the torch by:','["closing only the oxygen", "closing the fuel valve first, then the oxygen valve", "dropping the torch", "leaving both valves open"]'::jsonb,1,'Fuel off first ends the flame safely.','original'),
('127.821.d.6.B',3,'A cylinder cart carrying oxygen and fuel gas needs to be moved across the shop. The safe method is to:','["carry them by the valve", "roll them on their sides", "chain the cylinders upright and cap them", "stack them flat"]'::jsonb,2,'Secured, capped cylinders are stable.','original'),
('127.821.d.6.B',4,'If a cylinder valve will not close and gas hisses out, the first response is to:','["light it to burn off", "hide it in a closet", "strike it with a hammer", "move it outdoors away from ignition and notify the supervisor"]'::jsonb,3,'Leaks require evacuation and reporting.','original'),
('127.821.d.6.C',3,'On an oxy-fuel setup, the gauges that show cylinder contents and working pressure are part of the:','["regulators", "cutting table", "torch tip", "flux box"]'::jsonb,0,'Regulators control pressure.','original'),
('127.821.d.6.C',4,'The device installed between the hoses and the torch to stop a flame from traveling backward is a:','["gloves", "flashback arrestor", "slag hammer", "nozzle brush"]'::jsonb,1,'Arrestors stop flashbacks.','original'),
('127.821.d.6.D',3,'Before lighting the torch, the operator opens each torch valve briefly to clear the lines. This step is called:','["peening", "tacking", "purging", "grinding"]'::jsonb,2,'Purging clears air and mixed gas.','original'),
('127.821.d.6.D',4,'A common correct order during set-up is to:','["set the pressure before attaching the regulator", "open it fully and fast", "skip leak testing", "open the cylinder valve slowly, then set the regulator pressure"]'::jsonb,3,'Slow opening protects the regulator.','original'),
('127.821.d.6.E',3,'A student finds that a 1 in. plate needs a different tip and pressure than a 1/4 in. plate. The factor affecting the cut is the metal''s:','["thickness", "paint color", "brand name", "weight of the cart"]'::jsonb,0,'Thicker metal needs more heat and oxygen.','original'),
('127.821.d.6.E',4,'Which condition makes an oxy-fuel cut less clean?','["a steady travel speed", "heavy rust and mill scale on the surface", "clean bare steel", "a sharp tip"]'::jsonb,1,'Scale interferes with preheating.','original'),
('127.821.d.6.F',3,'To start a cut in the middle of a plate without an edge, the operator uses a technique called:','["tacking", "peening", "piercing", "bending"]'::jsonb,2,'Piercing starts a hole in the plate interior.','original'),
('127.821.d.6.F',4,'To cut a clean straight line, the operator should:','["wave the torch back and forth", "hold the tip against the plate", "move as fast as possible", "guide the torch along a straightedge at a steady speed"]'::jsonb,3,'A guide and steady speed produce straight cuts.','original'),
('127.821.d.6.G',3,'Which describes an acceptable oxy-fuel cut?','["a smooth edge with square corners and little slag", "a rounded top edge", "a heavy slag drip", "a rough, gouged edge"]'::jsonb,0,'Quality cuts are smooth and square.','original'),
('127.821.d.6.G',4,'Heavy slag clinging to the bottom of a cut usually shows the speed was:','["perfect", "too slow", "too fast to cut through", "unrelated"]'::jsonb,1,'Slow travel builds slag.','original'),
('127.821.d.6.H',3,'A shop compares acetylene with propane, propylene and MAPP-type gases for cutting. This is an evaluation of:','["paint colors", "electrode coatings", "alternative fuel gases", "helmet lenses"]'::jsonb,2,'Fuel choices differ in heat and cost.','original'),
('127.821.d.6.H',4,'A reason some shops choose propane over acetylene is that propane is usually:','["unable to burn", "hotter in the inner cone", "free of any hazard", "lower in cost"]'::jsonb,3,'Cost often drives fuel choice.','original'),
('127.821.d.7.A',3,'Before running a plasma cutter, Amir checks the work clamp, wears a face shield and keeps combustibles away. He is:','["using safe operating practices", "packing a tool", "setting a bid", "drawing a part"]'::jsonb,0,'Plasma cutting needs the same shop safety.','original'),
('127.821.d.7.A',4,'A plasma cutting operator should wear a shade-appropriate lens because the arc produces:','["cold light", "intense ultraviolet and visible light", "only sound", "no light"]'::jsonb,1,'Arc light injures eyes.','original'),
('127.821.d.7.B',3,'A plasma torch cuts metal by forcing gas through a small nozzle so that the gas becomes:','["a smooth foam", "a cold liquid", "a hot, electrically conductive stream", "a solid rod"]'::jsonb,2,'Plasma is an ionized gas.','original'),
('127.821.d.7.B',4,'Plasma arc cutting works on aluminum and stainless steel, unlike standard oxy-fuel cutting, because it:','["uses paint", "needs no electricity", "freezes the metal", "melts the metal with an extremely hot arc rather than burning it"]'::jsonb,3,'Plasma melts any conductive metal.','original'),
('127.821.d.7.C',3,'A plasma cutter requires a clean, dry air supply. If the compressed air has moisture, the cut will:','["be rough and the consumables will wear faster", "stop all arcs", "need less power", "be perfect"]'::jsonb,0,'Moisture harms cut quality.','original'),
('127.821.d.7.C',4,'Before connecting a plasma cutter to an air hose, the operator should:','["remove the regulator", "check the pressure and drain the moisture filter", "disconnect the ground", "increase the pressure to the maximum"]'::jsonb,1,'Proper air supply protects the torch.','original'),
('127.821.d.7.D',3,'The part of a plasma torch that wears out and must be replaced regularly, along with the electrode, is the:','["ground clamp", "power cord", "nozzle or tip", "handle grip"]'::jsonb,2,'Consumables include nozzle and electrode.','original'),
('127.821.d.7.D',4,'Which group lists consumable parts of a plasma torch?','["helmet, gloves and jacket", "drill, saw and hammer", "table, vise and clamp", "electrode, nozzle and shield cup"]'::jsonb,3,'These parts wear in use.','original'),
('127.821.d.7.E',3,'During set-up, the operator connects the work clamp to the base metal, sets the amperage for the thickness and adjusts the air pressure. This is the:','["correct set-up procedure for plasma arc cutting", "shutdown procedure", "cleanup step", "packing step"]'::jsonb,0,'Set-up follows manufacturer settings.','original'),
('127.821.d.7.E',4,'Cutting thicker steel with a plasma cutter generally requires:','["no amperage", "higher amperage and slower travel", "lower amperage and faster travel", "no air"]'::jsonb,1,'Thick metal needs more energy.','original'),
('127.821.d.7.F',3,'The width of metal removed by the cutting process is called:','["the bead", "the root", "the kerf", "the leg"]'::jsonb,2,'Kerf is the cut width.','original'),
('127.821.d.7.F',4,'The molten metal that sticks to the bottom edge of a cut is called:','["filler", "flux", "slag glass", "dross"]'::jsonb,3,'Dross is resolidified metal on a cut edge.','original'),
('127.821.d.7.G',3,'For an interior hole in a plate, a plasma cutter operator starts the cut with a:','["pierce", "tack", "bend", "grind"]'::jsonb,0,'Piercing starts a cut inside the plate.','original'),
('127.821.d.7.G',4,'To cut a beveled edge for a groove weld, the plasma torch is held:','["far from the plate", "at an angle to the plate surface", "upside down in the air", "at a right angle only"]'::jsonb,1,'Bevel cuts need a tilted torch.','original'),
('127.821.d.8.A',3,'Before striking an arc with a stick welder, Nia stands on a dry surface, checks her insulated gloves and places a screen around the area. This is:','["a delivery plan", "a cost estimate", "safe operating practice", "a drawing review"]'::jsonb,2,'Stick welding safety.','original'),
('127.821.d.8.A',4,'The electrode holder should be hung on an insulated hook while not in use so that it:','["cools faster", "looks neat only", "stays warm", "cannot touch the grounded table and cause an arc"]'::jsonb,3,'Live holders can arc.','original'),
('127.821.d.8.B',3,'On a stick welder, a setting where the current flows in one direction only is:','["direct current", "phase current", "pulse current", "alternating current"]'::jsonb,0,'DC flows one way.','original'),
('127.821.d.8.B',4,'With DC electrode positive (reverse polarity), the arc generally produces:','["no arc", "deeper base metal penetration", "no heat", "shallower penetration only"]'::jsonb,1,'DCEP gives deeper penetration.','original'),
('127.821.d.8.C',3,'In shielded metal arc welding, the coating on the electrode:','["conducts heat away from the plate", "cools the helmet", "produces shielding gas and slag to protect the weld", "paints the weld"]'::jsonb,2,'Flux shields the weld pool.','original'),
('127.821.d.8.C',4,'The rod stub length at which a welder normally stops welding to change electrodes is about:','["zero inches", "twelve inches", "a full rod", "two inches"]'::jsonb,3,'Short stubs are wasted and risk contact.','original'),
('127.821.d.8.D',3,'For a 1/8 in. E6013 electrode, the welder sets the amperage on the machine and checks polarity. This is part of:','["proper set-up for shielded metal arc welding", "shutdown for the day", "a safety walk-around", "a bid review"]'::jsonb,0,'Set-up depends on electrode and base metal.','original'),
('127.821.d.8.D',4,'If the amperage is set too high for the electrode size, the weld will likely show:','["perfect penetration", "excessive spatter and undercut", "no heat", "cold lap"]'::jsonb,1,'Too much current overheats the weld.','original'),
('127.821.d.8.E',3,'In the AWS classification E7018, the first two digits ''70'' refer to the electrode''s:','["diameter", "length", "minimum tensile strength of 70,000 psi", "brand"]'::jsonb,2,'First digits give tensile strength.','original'),
('127.821.d.8.E',4,'The last two digits ''18'' in E7018 tell the welder about the:','["lot number", "price", "rod length", "coating type and usable current"]'::jsonb,3,'Last digits show coating and current type.','original'),
('127.821.d.8.F',3,'For welding thick structural steel that needs high strength and low hydrogen, a welder should choose:','["an E7018 electrode", "a brazing rod", "an E6013 for tin", "a bare wire"]'::jsonb,0,'E7018 is low hydrogen.','original'),
('127.821.d.8.F',4,'A welder selects electrodes by matching the rod''s strength to the:','["color of the helmet", "strength and type of the base metal", "name of the supplier", "weight of the cart"]'::jsonb,1,'Match filler to base metal.','original'),
('127.821.d.8.G',3,'On a thick plate with a beveled groove, the welder lays a root pass, then fills with several more passes. This is:','["a flange weld", "a plug weld", "a multi-pass groove weld", "a spot weld"]'::jsonb,2,'Thick joints are welded in multiple passes.','original'),
('127.821.d.8.G',4,'Between passes on a multi-pass stick weld, the welder should:','["quench the plate in water", "add paint", "leave the slag in place", "remove the slag before the next pass"]'::jsonb,3,'Slag inclusions weaken welds.','original'),
('127.821.d.9.A',3,'Before starting a wire welder, Tomas checks gas flow, the drive rolls and the work area for flammables. He is:','["using safe operating practices", "reading a catalog", "writing a bid", "cleaning a window"]'::jsonb,0,'Pre-weld safety checks.','original'),
('127.821.d.9.A',4,'When welding with a shielding gas cylinder nearby, it should be:','["left loose", "chained upright and kept away from sparks", "placed under the arc", "laid flat"]'::jsonb,1,'Cylinder safety.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_118'
from (values
('127.821.d.9.B',3,'Tilting the gun to push the weld puddle instead of drag it changes the:','["wire color", "helmet shade", "weld angle and bead shape", "gas type"]'::jsonb,2,'Travel angle affects penetration.','original'),
('127.821.d.9.B',4,'If the electrode extension (stick-out) is too long on a wire welder, the result is typically:','["no change", "more penetration", "a quieter arc only", "less penetration and an unstable arc"]'::jsonb,3,'Long stick-out lowers current and heat.','original'),
('127.821.d.9.C',3,'In gas metal arc welding, the shielding gas is used to:','["protect the molten weld pool from the air", "color the bead", "cool the wire spool", "feed the wire"]'::jsonb,0,'Gas keeps oxygen and nitrogen out.','original'),
('127.821.d.9.C',4,'The consumable wire in a wire feed welder serves as:','["only the ground", "the electrode and the filler metal", "only the shielding gas", "only the handle"]'::jsonb,1,'Wire carries current and fills the joint.','original'),
('127.821.d.9.D',3,'A welder selects the wire size, threads it through the drive rolls and sets voltage and wire speed. This is:','["a tear-down", "a repair", "proper set-up for gas metal arc welding", "a bid"]'::jsonb,2,'Set-up before welding.','original'),
('127.821.d.9.D',4,'Shielding gas flow for GMAW is usually checked with a:','["stopwatch", "micrometer", "tape measure", "flowmeter on the regulator"]'::jsonb,3,'Flowmeters show cubic feet per hour.','original'),
('127.821.d.9.E',3,'In the wire classification ER70S-6, the ''70'' indicates:','["a minimum tensile strength of 70,000 psi", "a speed of 70 in/min", "a weight of 70 lb", "a diameter of 0.70 in."]'::jsonb,0,'Same system as stick rods.','original'),
('127.821.d.9.E',4,'In ER70S-6, the ''S'' means the wire is:','["a stainless wire", "a solid wire", "a stick", "a flux cored wire"]'::jsonb,1,'S = solid.','original'),
('127.821.d.9.F',3,'For welding mild steel with GMAW, a common filler is:','["a tungsten electrode", "an aluminum wire", "ER70S-6 solid wire", "a brass rod"]'::jsonb,2,'ER70S-6 suits mild steel.','original'),
('127.821.d.9.F',4,'Welding aluminum with GMAW requires matching the wire to the base metal, so the welder uses:','["a steel wire", "no wire", "a copper rod", "an aluminum filler wire"]'::jsonb,3,'Match filler to base metal.','original'),
('127.821.d.9.G',3,'A student welds a T-joint and a beveled butt joint in flat, horizontal, vertical and overhead positions. She is performing:','["fillet and groove welds in all positions", "only flat welds", "only tack welds", "only cutting"]'::jsonb,0,'All-position welding.','original'),
('127.821.d.9.G',4,'For a vertical weld with GMAW, a common practice is to:','["stop shielding gas", "use a lower heat setting and weave carefully", "use maximum heat", "hold the gun backward"]'::jsonb,1,'Lower heat prevents sagging.','original'),
('127.821.d.10.A',3,'A welder using flux cored wire on a field site checks her cables, gas needs and the fire hazards nearby. She is:','["drawing a part", "setting a price", "using safe operating practices", "reading a code"]'::jsonb,2,'Flux cored safety.','original'),
('127.821.d.10.A',4,'Fumes from flux cored welding are heavier than from solid wire, so the shop should provide:','["a closed room", "no airflow", "extra lighting only", "adequate ventilation or fume extraction"]'::jsonb,3,'Ventilation protects the welder.','original'),
('127.821.d.10.B',3,'Adjusting the gun angle and the stick-out when welding with flux cored wire changes the:','["penetration and bead profile", "wire color", "helmet shade", "gas cylinder size"]'::jsonb,0,'Angle and extension affect the weld.','original'),
('127.821.d.10.B',4,'A drag (backhand) travel angle on flux cored welding generally gives:','["no slag", "deeper penetration and a taller bead", "shallower penetration", "no arc"]'::jsonb,1,'Drag angle increases penetration.','original'),
('127.821.d.10.C',3,'Flux cored arc welding differs from solid-wire GMAW because the wire contains:','["paint", "no metal", "flux in its core that forms slag and shielding", "only copper"]'::jsonb,2,'The core provides protection.','original'),
('127.821.d.10.C',4,'Some flux cored wires, called self-shielded, can weld without:','["any electricity", "a ground clamp", "a helmet", "an external shielding gas"]'::jsonb,3,'Self-shielded wires create their own gas.','original'),
('127.821.d.10.D',3,'After loading flux cored wire, the welder sets the tension, polarity and wire speed for the diameter. This is:','["proper set-up for flux cored arc welding", "a cleanup", "a repair", "a bid"]'::jsonb,0,'Set-up before welding.','original'),
('127.821.d.10.D',4,'Many self-shielded flux cored wires run on:','["AC only", "DC electrode negative", "no current", "DC electrode positive only"]'::jsonb,1,'Self-shielded wires often use DCEN.','original'),
('127.821.d.10.E',3,'In the classification E71T-1, the ''T'' tells the welder that the electrode is:','["a solid wire", "a brazing rod", "a tubular (flux cored) wire", "a stick"]'::jsonb,2,'T = tubular.','original'),
('127.821.d.10.E',4,'In E71T-1, the ''7'' shows the minimum tensile strength is:','["700 psi", "700,000 psi", "7,000 psi", "70,000 psi"]'::jsonb,3,'Same system as other AWS electrodes.','original'),
('127.821.d.10.F',3,'A welder picking filler for mild steel with flux cored welding should match the:','["wire classification to the base metal strength", "wire color to the plate", "price to the table", "spool weight to the gun"]'::jsonb,0,'Match filler to base metal.','original'),
('127.821.d.10.F',4,'For outdoor, windy conditions on mild steel, a good filler is:','["a tungsten rod", "a self-shielded flux cored wire", "a solid wire with gas only", "a bare brazing rod"]'::jsonb,1,'No gas to blow away.','original'),
('127.821.d.10.G',3,'A student welds T-joint fillets and beveled groove joints with flux cored wire in each position. This is:','["only tacking", "only grinding", "fillet and groove welds in all positions", "only gouging"]'::jsonb,2,'All-position practice.','original'),
('127.821.d.10.G',4,'After each flux cored pass, the welder should:','["paint it", "leave it on", "quench it", "remove the slag before the next pass"]'::jsonb,3,'Slag must be cleaned.','original'),
('127.821.d.11.A',3,'Before starting a TIG weld, Caleb checks the gas hose, puts on a helmet with a suitable lens and clears the area of solvent. He is:','["using safe operating practices", "reading a menu", "setting a bid", "planning lunch"]'::jsonb,0,'GTAW safety.','original'),
('127.821.d.11.A',4,'Cleaning solvents such as those containing chlorine must be kept away from TIG welding because arc light can turn them into:','["smooth metal", "toxic gases", "pure water", "nothing"]'::jsonb,1,'Chlorinated solvents form phosgene.','original'),
('127.821.d.11.B',3,'When TIG welding aluminum, a welder normally selects:','["direct current only", "pulse only on steel", "alternating current", "no current"]'::jsonb,2,'AC cleans the oxide layer.','original'),
('127.821.d.11.B',4,'For most steel and stainless steel TIG welding, the common current is:','["DC electrode positive", "AC only", "no current", "DC electrode negative"]'::jsonb,3,'DCEN gives deep penetration.','original'),
('127.821.d.11.C',3,'A welder uses a 2% thoriated or lanthanated tungsten for steel. She is identifying:','["a common type of tungsten electrode", "a type of paint", "a type of cable", "a type of table"]'::jsonb,0,'Tungsten types are color coded.','original'),
('127.821.d.11.C',4,'A filler rod classified ER308 is generally used to weld:','["cast iron", "stainless steel", "copper", "aluminum"]'::jsonb,1,'308 matches 304 stainless.','original'),
('127.821.d.11.D',3,'The welder grinds the tungsten to a point, sets the gas flow, selects the current and checks the foot pedal. This is:','["a tool storage", "a pricing step", "proper set-up for gas tungsten arc welding", "a shutdown"]'::jsonb,2,'Set-up before welding.','original'),
('127.821.d.11.D',4,'The shielding gas most often used for TIG welding is:','["acetylene", "hydrogen alone", "oxygen", "argon"]'::jsonb,3,'Argon is the standard.','original'),
('127.821.d.11.E',3,'A student TIG welds fillet and groove joints in all four positions. She is:','["performing welds in all positions", "only grinding", "only cutting", "only brazing"]'::jsonb,0,'All-position proficiency.','original'),
('127.821.d.11.E',4,'A TIG welder keeps the filler rod''s hot end:','["in the air", "inside the shielding gas envelope", "outside it", "in water"]'::jsonb,1,'Prevents contamination.','original'),
('127.821.d.11.F',3,'A shop uses TIG on thin carbon steel, stainless and aluminum parts. This shows welding on:','["only one metal", "wood", "a variety of metals", "plastic"]'::jsonb,2,'TIG works on many metals.','original'),
('127.821.d.11.F',4,'Before TIG welding aluminum, the surface should be cleaned of:','["shiny finish", "nothing", "clean metal only", "oxide and contaminants"]'::jsonb,3,'Oxide melts at a higher temperature.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
